#### Variation 3: Application-Level Rate Limiting (ASP.NET Core Middleware)

**Context**: For scenarios requiring fine-grained rate limiting logic not available in API gateway (e.g., per-user limits within single OAuth client, business logic-based limits).

**Implementation**:

```csharp
// ASP.NET Core 7+ built-in rate limiting middleware
using Microsoft.AspNetCore.RateLimiting;
using System.Threading.RateLimiting;

var builder = WebApplication.CreateBuilder(args);

// Configure rate limiting services
builder.Services.AddRateLimiter(options =>
{
    // Fixed window limiter: Simple but less accurate
    options.AddFixedWindowLimiter("fixed", fixedOptions =>
    {
        fixedOptions.PermitLimit = 1000;
        fixedOptions.Window = TimeSpan.FromMinutes(1);
        fixedOptions.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
        fixedOptions.QueueLimit = 100; // Queue up to 100 requests when limit hit
    });

    // Sliding window limiter: More accurate, prevents boundary gaming
    options.AddSlidingWindowLimiter("sliding", slidingOptions =>
    {
        slidingOptions.PermitLimit = 1000;
        slidingOptions.Window = TimeSpan.FromMinutes(1);
        slidingOptions.SegmentsPerWindow = 6; // 10-second segments
        slidingOptions.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
        slidingOptions.QueueLimit = 50;
    });

    // Token bucket limiter: Supports bursts
    options.AddTokenBucketLimiter("token_bucket", tokenOptions =>
    {
        tokenOptions.TokenLimit = 1500; // Bucket capacity (50% burst)
        tokenOptions.ReplenishmentPeriod = TimeSpan.FromSeconds(1);
        tokenOptions.TokensPerPeriod = 16; // ~1000/min refill rate
        tokenOptions.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
        tokenOptions.QueueLimit = 100;
    });

    // Concurrency limiter: Limit simultaneous requests (not time-based)
    options.AddConcurrencyLimiter("concurrency", concurrencyOptions =>
    {
        concurrencyOptions.PermitLimit = 100; // Max 100 concurrent requests
        concurrencyOptions.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
        concurrencyOptions.QueueLimit = 500;
    });

    // Per-user rate limiting (custom partition)
    options.AddPolicy("per_user", httpContext =>
    {
        var userId = httpContext.User.FindFirst("sub")?.Value ?? "anonymous";

        return RateLimitPartition.GetTokenBucketLimiter(userId, key =>
            new TokenBucketRateLimiterOptions
            {
                TokenLimit = 500, // 500 requests per user
                ReplenishmentPeriod = TimeSpan.FromMinutes(1),
                TokensPerPeriod = 500,
                QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
                QueueLimit = 50
            });
    });

    // Per-API-key rate limiting with Redis distributed cache
    options.AddPolicy("per_api_key", httpContext =>
    {
        var apiKey = httpContext.Request.Headers["X-API-Key"].FirstOrDefault() ?? "no_key";

        // Determine tier from API key metadata (stored in database/cache)
        var tier = DetermineApiKeyTier(apiKey); // free, standard, enterprise

        var tokenLimit = tier switch
        {
            "free" => 100,
            "standard" => 1000,
            "enterprise" => 10000,
            _ => 100
        };

        return RateLimitPartition.GetTokenBucketLimiter(apiKey, key =>
            new TokenBucketRateLimiterOptions
            {
                TokenLimit = tokenLimit,
                ReplenishmentPeriod = TimeSpan.FromMinutes(1),
                TokensPerPeriod = tokenLimit,
                QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
                QueueLimit = 100
            });
    });

    // Operation-specific rate limiting (expensive operations)
    options.AddPolicy("bulk_export", httpContext =>
    {
        var userId = httpContext.User.FindFirst("sub")?.Value ?? "anonymous";

        return RateLimitPartition.GetFixedWindowLimiter($"bulk_export:{userId}", key =>
            new FixedWindowRateLimiterOptions
            {
                PermitLimit = 10, // Only 10 bulk exports per hour
                Window = TimeSpan.FromHours(1),
                QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
                QueueLimit = 5
            });
    });

    // Global rate limiter rejection handler
    options.OnRejected = async (context, cancellationToken) =>
    {
        context.HttpContext.Response.StatusCode = StatusCodes.Status429TooManyRequests;

        // Extract rate limit metadata
        var lease = context.Lease;
        var retryAfter = lease.TryGetMetadata(MetadataName.RetryAfter, out var retryAfterValue)
            ? retryAfterValue.TotalSeconds
            : 60;

        context.HttpContext.Response.Headers["Retry-After"] = retryAfter.ToString();
        context.HttpContext.Response.Headers["X-RateLimit-Limit"] = "1000";
        context.HttpContext.Response.Headers["X-RateLimit-Remaining"] = "0";

        await context.HttpContext.Response.WriteAsJsonAsync(new
        {
            error = "rate_limit_exceeded",
            error_description = "Rate limit exceeded. Please retry after the specified time.",
            retry_after_seconds = (int)retryAfter,
            documentation_url = "https://developers.gainwell.com/docs/rate-limiting"
        }, cancellationToken);

        // Log rate limit rejection
        var logger = context.HttpContext.RequestServices.GetRequiredService<ILogger<Program>>();
        logger.LogWarning(
            "Rate limit exceeded. Path: {Path}, User: {UserId}, Limit: {Limit}",
            context.HttpContext.Request.Path,
            context.HttpContext.User.FindFirst("sub")?.Value,
            context.Lease.Count
        );
    };
});

var app = builder.Build();

// Enable rate limiting middleware
app.UseRateLimiter();

// Apply rate limiting to specific endpoints
app.MapGet("/api/v1/claims", async (ClaimsService claimsService) =>
{
    var claims = await claimsService.GetClaimsAsync();
    return Results.Ok(claims);
})
.RequireRateLimiting("per_user"); // Apply per-user rate limit

app.MapPost("/api/v1/claims/bulk-export", async (ExportService exportService) =>
{
    var exportId = await exportService.StartBulkExportAsync();
    return Results.Accepted($"/api/v1/exports/{exportId}");
})
.RequireRateLimiting("bulk_export"); // Apply strict limit for expensive operation

app.MapGet("/api/v1/eligibility/verify", async (EligibilityService eligibilityService, string memberId) =>
{
    var result = await eligibilityService.VerifyEligibilityAsync(memberId);
    return Results.Ok(result);
})
.RequireRateLimiting("per_api_key"); // Apply API key-based tiered limits

app.Run();

// Helper function to determine API key tier
string DetermineApiKeyTier(string apiKey)
{
    // In production: Query database or Redis cache for API key metadata
    // For demo: Simple prefix-based logic
    if (apiKey.StartsWith("ent_")) return "enterprise";
    if (apiKey.StartsWith("std_")) return "standard";
    return "free";
}
```

**Distributed Rate Limiting with Redis (Custom Middleware):**

```csharp
// Custom distributed rate limiting middleware using Redis
public class RedisRateLimitingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IConnectionMultiplexer _redis;
    private readonly ILogger<RedisRateLimitingMiddleware> _logger;

    public RedisRateLimitingMiddleware(
        RequestDelegate next,
        IConnectionMultiplexer redis,
        ILogger<RedisRateLimitingMiddleware> logger)
    {
        _next = next;
        _redis = redis;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Extract rate limit key (user ID, API key, IP address)
        var rateLimitKey = ExtractRateLimitKey(context);
        var endpoint = context.Request.Path.Value;
        var redisKey = $"rate_limit:{rateLimitKey}:{endpoint}";

        // Get Redis database
        var db = _redis.GetDatabase();

        // Token bucket algorithm using Redis Lua script
        var luaScript = @"
            local key = KEYS[1]
            local refill_rate = tonumber(ARGV[1])
            local bucket_capacity = tonumber(ARGV[2])
            local current_time = tonumber(ARGV[3])

            local bucket_data = redis.call('GET', key)
            local tokens, last_refill

            if bucket_data then
                local data = cjson.decode(bucket_data)
                tokens = tonumber(data.tokens)
                last_refill = tonumber(data.last_refill)
            else
                tokens = bucket_capacity
                last_refill = current_time
            end

            local time_elapsed = current_time - last_refill
            local tokens_to_add = time_elapsed * refill_rate
            tokens = math.min(tokens + tokens_to_add, bucket_capacity)

            if tokens >= 1 then
                tokens = tokens - 1
                local new_bucket_data = cjson.encode({
                    tokens = tokens,
                    last_refill = current_time
                })
                redis.call('SET', key, new_bucket_data)
                redis.call('EXPIRE', key, 3600)
                return {1, tokens, bucket_capacity}
            else
                return {0, tokens, bucket_capacity}
            end
        ";

        try
        {
            var refillRate = 1000.0 / 60.0; // 1000 requests per minute = 16.67/sec
            var bucketCapacity = 1500; // 50% burst allowance
            var currentTime = DateTimeOffset.UtcNow.ToUnixTimeSeconds();

            var result = await db.ScriptEvaluateAsync(
                luaScript,
                new RedisKey[] { redisKey },
                new RedisValue[] { refillRate, bucketCapacity, currentTime }
            );

            var resultArray = (RedisValue[])result;
            var allowed = (int)resultArray[0] == 1;
            var tokensRemaining = (int)resultArray[1];
            var limitCapacity = (int)resultArray[2];

            // Set rate limit headers
            context.Response.Headers["X-RateLimit-Limit"] = limitCapacity.ToString();
            context.Response.Headers["X-RateLimit-Remaining"] = tokensRemaining.ToString();
            context.Response.Headers["X-RateLimit-Reset"] = (currentTime + 60).ToString();

            if (!allowed)
            {
                // Rate limit exceeded
                context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
                context.Response.Headers["Retry-After"] = "60";

                await context.Response.WriteAsJsonAsync(new
                {
                    error = "rate_limit_exceeded",
                    error_description = "Rate limit exceeded. Please retry after 60 seconds.",
                    retry_after_seconds = 60,
                    limit = limitCapacity,
                    remaining = 0
                });

                _logger.LogWarning(
                    "Rate limit exceeded. Key: {Key}, Endpoint: {Endpoint}",
                    rateLimitKey, endpoint
                );

                return; // Don't call next middleware
            }

            // Rate limit passed, continue pipeline
            await _next(context);
        }
        catch (RedisException ex)
        {
            _logger.LogError(ex, "Redis rate limiting failed. Failing open (allowing request).");

            // Fail open: Allow request if Redis unavailable
            await _next(context);
        }
    }

    private string ExtractRateLimitKey(HttpContext context)
    {
        // Priority: OAuth user ID > API key > IP address
        var userId = context.User.FindFirst("sub")?.Value;
        if (!string.IsNullOrEmpty(userId))
        {
            return $"user:{userId}";
        }

        var apiKey = context.Request.Headers["X-API-Key"].FirstOrDefault();
        if (!string.IsNullOrEmpty(apiKey))
        {
            return $"apikey:{apiKey}";
        }

        var ipAddress = context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
        return $"ip:{ipAddress}";
    }
}

// Register middleware in Program.cs
app.UseMiddleware<RedisRateLimitingMiddleware>();
```

**Outcomes:**
- **Application-level control**: Fine-grained rate limiting logic based on business rules
- **Distributed consistency**: Redis-based counters synchronized across multiple app instances
- **Flexible policies**: Per-user, per-API-key, per-endpoint, per-operation limits
- **Token bucket with burst**: Smooths traffic spikes while preventing abuse
- **Fail-open design**: Redis failure doesn't block legitimate traffic
- **Rich telemetry**: Detailed logging and metrics for capacity planning

