#### Express: express-rate-limit

Install `express-rate-limit` and, for multi-replica deployments, the `rate-limit-redis` store:

```typescript
import rateLimit from 'express-rate-limit';
import { RedisStore } from 'rate-limit-redis';
import { createClient } from 'redis';

const redisClient = createClient({ url: process.env.REDIS_URL });
await redisClient.connect();

// Standard API rate limit: 200 requests per 15 minutes per IP/consumer
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 200,
  standardHeaders: true,    // Return RateLimit-* headers (RFC 6585 draft)
  legacyHeaders: false,     // Disable X-RateLimit-* legacy headers
  store: new RedisStore({
    sendCommand: (...args: string[]) => redisClient.sendCommand(args),
  }),
  keyGenerator: (req) => {
    // Key on OAuth client ID if present, otherwise IP address
    const clientId = (req as { oauthClientId?: string }).oauthClientId;
    return clientId ?? req.ip ?? 'anonymous';
  },
  message: {
    type: 'https://api.gainwelltechnologies.com/problems/rate-limit-exceeded',
    title: 'Too Many Requests',
    status: 429,
    detail: 'Rate limit exceeded. Retry after the period indicated in the Retry-After header.',
  },
  skip: (req) => req.path === '/health' || req.path === '/ready',
});

// Stricter limit for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  standardHeaders: true,
  legacyHeaders: false,
  store: new RedisStore({
    sendCommand: (...args: string[]) => redisClient.sendCommand(args),
  }),
  message: {
    type: 'https://api.gainwelltechnologies.com/problems/rate-limit-exceeded',
    title: 'Too Many Requests',
    status: 429,
    detail: 'Authentication rate limit exceeded.',
  },
});

app.use('/api/', apiLimiter);
app.use('/auth/', authLimiter);
```

> **Multi-replica deployments**: In-memory rate limit counters (the default store) are not shared across Node.js process instances. Use `rate-limit-redis` or another shared store whenever the service runs with more than one replica.

