#### Fastify: @fastify/rate-limit

For Fastify services, use the official `@fastify/rate-limit` plugin:

```typescript
import Fastify from 'fastify';
import rateLimit from '@fastify/rate-limit';
import Redis from 'ioredis';

const fastify = Fastify({ logger: true });
const redis = new Redis(process.env.REDIS_URL);

await fastify.register(rateLimit, {
  max: 200,
  timeWindow: '15 minutes',
  redis,                        // Shared Redis store for multi-replica deployments
  keyGenerator: (request) => {
    // Key on OAuth client ID claim if present
    const clientId = (request as { oauthClientId?: string }).oauthClientId;
    return clientId ?? request.ip ?? 'anonymous';
  },
  errorResponseBuilder: (_request, context) => ({
    type: 'https://api.gainwelltechnologies.com/problems/rate-limit-exceeded',
    title: 'Too Many Requests',
    status: 429,
    detail: `Rate limit of ${context.max} requests per ${context.after} exceeded.`,
    retryAfter: context.ttl,
  }),
  // Skip health check endpoints
  skip: (request) =>
    request.url === '/health' || request.url === '/ready',
});

// Route-level override — tighter limit for auth routes
fastify.route({
  method: 'POST',
  url: '/auth/token',
  config: { rateLimit: { max: 20, timeWindow: '15 minutes' } },
  handler: async (_request, reply) => {
    reply.send({ message: 'auth endpoint' });
  },
});
```

